import argparse
import logging
import signal
import socket
import sys
import time

import gpiozero
import spidev

parser = argparse.ArgumentParser(description='Irrigation system')
parser.add_argument('--moisture_threshold', type=int, default=30, help='Moisture threshold')
parser.add_argument('--web_port', type=int, default=8080, help='Web server port')
parser.add_argument('--log_file', type=str, default='irrigation.log', help='Log file')
parser.add_argument('--valve_pin', type=int, default=17, help='Valve pin')
parser.add_argument('--spi_channel', type=int, default=0, help='SPI channel')
args = parser.parse_args()

logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s %(message)s')

valve = gpiozero.DigitalOutputDevice(args.valve_pin)
spi = spidev.SpiDev()
spi.open(0, args.spi_channel)
spi.max_speed_hz = 1000000

def read_moisture():
    try:
        response = spi.xfer2([1, 8, 0])
        if response == [1, 8, 0] or response == [1, 255, 0]:
            raise Exception('Sensor not connected')
        return response[1] << 8 | response[2]
    except Exception as e:
        logging.error(e)
        return None

def get_status():
    moisture = read_moisture()
    if moisture is None:
        return {'moisture': None, 'valve': None, 'threshold': None}
    return {'moisture': moisture, 'valve': valve.value, 'threshold': args.moisture_threshold}

def toggle_valve():
    valve.toggle()

def run_web_server():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind(('0.0.0.0', args.web_port))
    server.listen(1)
    while True:
        try:
            conn, addr = server.accept()
            data = conn.recv(1024)
            if not data:
                continue
            try:
                command = eval(data.decode('utf-8'))
                if command['action'] == 'get_status':
                    response = get_status()
                elif command['action'] == 'toggle_valve':
                    toggle_valve()
                    response = get_status()
                else:
                    response = {'error': 'Invalid command'}
            except Exception as e:
                logging.error(e)
                response = {'error': 'Invalid command'}
            conn.sendall(bytes(str(response), 'utf-8'))
            conn.close()
        except Exception as e:
            logging.error(e)
            conn.close()

def run_irrigation():
    while True:
        try:
            moisture = read_moisture()
            if moisture is None:
                continue
            if moisture < args.moisture_threshold:
                valve.on()
            elif moisture > args.moisture_threshold + 10:
                valve.off()
            logging.info(f'Moisture: {moisture}, valve: {valve.value}')
            time.sleep(5)
        except Exception as e:
            logging.error(e)

def signal_handler(sig, frame):
    valve.close()
    spi.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

run_web_server()
run_irrigation()
