import spidev
import time
import numpy as np
import csv
import logging

class SoilMoistureSensor:
    def __init__(self, dry=820, wet=400):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1200000
        self.dry = dry
        self.wet = wet
        self.history = []

    def read_raw(self):
        frame = [0x01, 0x80, 0x00, 0x00]
        response = self.spi.xfer2(frame)
        return (response[1] << 2) | (response[2] >> 6)

    def read_moisture(self):
        raw = self.read_raw()
        if raw == 0 or raw == 1023:
            return None
        return (raw - self.wet) / (self.dry - self.wet) * 100

    def read_history(self):
        return self.history

    def read_mean(self):
        return np.mean(self.history)

    def read_std(self):
        return np.std(self.history)

    def read_all(self):
        return self.read_moisture(), self.read_mean(), self.read_std()

    def log(self, moisture):
        self.history.append(moisture)
        with open('soil_moisture_log.csv', 'a') as f:
            writer = csv.writer(f)
            writer.writerow([time.time(), moisture])

