import logging
import queue
import time
import threading
import spidev
import RPi.GPIO as GPIO

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio_setup = False
        self.stop_event = threading.Event()
        self.stop_event.clear()
        self.thread = threading.Thread(target=self.run)
        self.thread.start()

    def run(self):
        if self.sensor_type == 'digital':
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pins, GPIO.IN)
            self.gpio_setup = True
        else:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
        while not self.stop_event.is_set():
            try:
                if self.sensor_type == 'digital':
                    if GPIO.input(self.gpio_pins) == 1:
                        self.log_queue.put(self.sensor_id)
                        time.sleep(0.1)
                else:
                    for channel in self.channels:
                        r = self.spi.xfer2([1, (8 + channel) << 4, 0])
                        if r[1] & 128 == 0:
                            value = ((r[1] & 3) << 8) + r[2]
                            if value >= self.threshold:
                                self.log_queue.put(self.sensor_id)
                                time.sleep(0.1)
            except Exception as e:
                logging.error(e)
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.stop_event.set()
        self.thread.join()
        if self.sensor_type == 'digital':
            if self.gpio_setup:
                GPIO.cleanup()
        else:
            if self.spi:
                self.spi.close()

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--sensor_type', type=str, required=True)
    parser.add_argument('--threshold', type=int, required=True)
    parser.add_argument('--sample_rate', type=int, required=True)
    parser.add_argument('--log_file', type=str, required=True)
    parser.add_argument('--gpio_pins', type=int, nargs='+', required=True)
    parser.add_argument('--channels', type=int, nargs='+', required=True)
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', type=str, nargs='+', required=True)
    args = parser.parse_args()
    log_queue = queue.Queue()
    log_thread = threading.Thread(target=log_queue_handler, args=(log_queue, args.log_file))
    log_thread.start()
    sensors = []
    for sensor_id in args.sensor_ids:
        sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue))
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        log_queue.put(None)
        log_thread.join()

def log_queue_handler(log_queue, log_file):
    import logging
    logging.basicConfig(filename=log_file, level=logging.INFO)
    while True:
        sensor_id = log_queue.get()
        if sensor_id is None:
            break
        logging.info(sensor_id)

if __name__ == '__main__':
    main()

import spidev
import time
import signal
import sys

class MCP3008:
    def __init__(self, bus=0, device=0, channel=0):
        self.bus = bus
        self.device = device
        self.channel = channel
        self.spi = spidev.SpiDev()
        self.spi.open(bus, device)
        self.spi.max_speed_hz = 1000000

    def read(self):
        try:
            r = self.spi.xfer2([1, (8 + self.channel) << 4, 0])
            adc = ((r[1] & 3) << 8) + r[2]
            return adc
        except OSError as e:
            print(e)
            return None

    def close(self):
        self.spi.close()

def signal_handler(signal, frame):
    print('You pressed Ctrl+C!')
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    adc = MCP3008()
    while True:
        adc_value = adc.read()
        if adc_value is not None:
            voltage = (adc_value / 1023) * 3.3
            ppm = voltage * 200
            if ppm < 150:
                print(f'Safe: {ppm:.2f} ppm')
            elif ppm < 400:
                print(f'Warning: {ppm:.2f} ppm')
            else:
                print(f'Danger: {ppm:.2f} ppm')
        time.sleep(0.5)

if __name__ == '__main__':
    main()

