            humidity_percent = bme280.humidity
            if pressure_pa < 70000 or pressure_pa > 110000 or temperature_c < -20 or temperature_c > 50 or humidity_percent < 0 or humidity_percent > 100:
                logging.warning('Invalid data from BME280')
                continue
            c.execute('INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?, ?)', (timestamp, sensor2_type, sensor2_id, pressure_pa, temperature_c, humidity_percent))
        if ms8607:
            pressure_pa = ms8607.pressure
            temperature_c = ms8607.temperature
            humidity_percent = ms8607.humidity
            if pressure_pa < 70000 or pressure_pa > 110000 or temperature_c < -20 or temperature_c > 50 or humidity_percent < 0 or humidity_percent > 100:
                logging.warning('Invalid data from MS8607')
                continue
            c.execute('INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?, ?)', (timestamp, sensor3_type, sensor3_id, pressure_pa, temperature_c, humidity_percent))
        conn.commit()
    except OSError:
        logging.error('Failed to read from sensor')
    time.sleep(sampling_interval_seconds)

import os
import sys
import time
import signal
import random
import board
import busio
import adafruit_amg88xx
import gpiozero

def detect_human(thermal_data):
    for pixel in thermal_data:
        if pixel > 30:
            return True
    return False

def trigger_alert(buzzer):
    buzzer.on()
    time.sleep(1)
    buzzer.off()

def main():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        try:
            sensor = adafruit_amg88xx.AMG88XX(i2c)
        except OSError:
            sensor = None
        buzzer = gpiozero.Buzzer(17)
        while True:
            if sensor:
                thermal_data = sensor.pixels
            else:
                thermal_data = [random.randint(20, 45) for _ in range(64)]
            if detect_human(thermal_data):
                trigger_alert(buzzer)
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        buzzer.close()
        if sensor:
            sensor.deinit()

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal.SIG_DFL)
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    main()

#!/usr/bin/env python3

import smbus2
import time
from gpiozero import Button

# Set up the I2C bus
bus = smbus2.SMBus(1)
address = 0x20

# Set up the interrupt pin
interrupt_pin = Button(17, pull_up=True)

# Function to read the sensor values
def read_sensors():
    try:
        data = bus.read_byte(address)
        for i in range(8):
            if (data >> i) & 1 == 0:
                print(f"Obstacle detected by sensor {i}")
    except IOError:
        print("Error reading from I2C bus")

# Function to handle the interrupt
def interrupt_handler():
    read_sensors()

# Register the interrupt handler
interrupt_pin.when_pressed = interrupt_handler

# Main loop
try:
    while True:
        time.sleep(1)
except KeyboardInterrupt:
    print("Exiting...")
finally:
    # Clean up GPIO resources
    interrupt_pin.close()

