def initialize_resources():
    initialize_camera()
    initialize_object_detector()
    initialize_config()
    initialize_mail_config()


def release_resources():
    global camera
    if camera:
        camera.close()


def check_for_objects():
    global last_email_sent_at
    while True:
        try:
            if config.classifier_name == 'motion_detector':
                jpeg_bytes, detected = object_detector.get_object_with_basic_motion_detection()
            else:
                jpeg_bytes, detected = object_detector.get_object(config.classifier_name)
        except Exception as e:
            logging.error(f'Error checking for objects: {e}')
            continue

        if detected and config.send_email_notifications:
            if last_email_sent_at is None or time.time() - last_email_sent_at >= config.email_send_interval:
                try:
                    mail_config.send_email(jpeg_bytes, config)
                    last_email_sent_at = time.time()
                except Exception as e:
                    logging.error(f'Error sending email: {e}')

        time.sleep(1)


@app.route('/')
def index():
    return render_template('index.html', config=config)


@app.route('/video_feed')
def video_feed():
    return Response(gen_frames(), mimetype='multipart/x-mixed-replace; boundary=frame')


def gen_frames():
    while True:
        try:
            jpeg_bytes = object_detector.get_frame()
        except Exception as e:
            logging.error(f'Error getting frame: {e}')
            continue

        yield (b'--frame\r\n'
               b'Content-Type: image/jpeg\r\n\r\n' + jpeg_bytes + b'\r\n')


def main():
    initialize_resources()
    atexit.register(release_resources)

    signal.signal(signal.SIGINT, signal.SIG_DFL)
    signal.signal(signal.SIGTERM, signal.SIG_DFL)

    check_for_objects_thread = threading.Thread(target=check_for_objects)
    check_for_objects_thread.start()

    app.run(host='0.0.0.0', port=80, debug=True)


if __name__ == '__main__':
    main()
