import io
import logging
import numpy as np
import picamera2
import cv2

class CameraStreamBuffer:
    def __init__(self, camera):
        self.camera = camera
        self.buffer = io.BytesIO()
        self.frame_type = None
        self.frame_complete = False

    def write(self, data):
        try:
            self.buffer.write(data)
            if self.frame_complete:
                self.buffer.seek(0)
                self.frame_complete = False
                self.frame_type = None
            else:
                metadata = self.camera.current_configuration()['encode']
                if metadata['frame_type'] != 1:
                    self.frame_complete = True
                    self.frame_type = metadata['frame_type']
                    self.buffer.seek(0)
                    # TODO: flush buffer to output sink
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logging.error(e)

class MotionDetectionBuffer:
    def __init__(self, callback):
        self.callback = callback
        self.previous_frame = None

    def write(self, data):
        try:
            if data.startswith(b'\xff\xd8'):
                frame = cv2.imdecode(np.frombuffer(data, dtype=np.uint8), cv2.IMREAD_COLOR)
                if self.previous_frame is not None:
                    self.callback(self.previous_frame, frame)
                self.previous_frame = frame
        except Exception as e:
            logging.error(e)

