from typing import List, Optional

import PIL.Image
import PIL.ImageOps
import paho.mqtt.client as mqtt

from luma.core.render import canvas

logger = logging.getLogger(__name__)


class Frame:
    def __init__(self, image: PIL.Image.Image, duration: int, loop: int):
        self.image = image
        self.duration = duration
        self.loop = loop


class AnimatedGif:
    def __init__(self, display, width: int = None, height: int = None, folder: str = None):
        self.display = display
        self.width = width or display.width
        self.height = height or display.height
        self.folder = folder
        self.files = []
        self.index = 0
        self.frames = []
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message
        self.mqtt_client.connect("localhost", 1883, 60)
        self.mqtt_client.loop_start()
        self._is_running = False

    def on_connect(self, client, userdata, flags, rc):
        logger.info("Connected with result code " + str(rc))
        client.subscribe("gif/folder")

    def on_message(self, client, userdata, msg):
        logger.info(f"Received message: {msg.topic} {msg.payload}")
        if msg.topic == "gif/folder":
            self.folder = msg.payload.decode()
            self.load_files(self.folder)

    def load_files(self, folder: str) -> None:
        self.files = []
        for file in glob.glob(os.path.join(folder, "*.gif")):
            try:
                with PIL.Image.open(file) as img:
                    if img.is_animated:
                        self.files.append(file)
                    else:
                        logger.warning(f"File {file} is not animated")
            except PIL.UnidentifiedImageError:
                logger.warning(f"File {file} is not a valid image")
        if not self.files:
            raise FileNotFoundError("No valid animated GIF files found")

    def preload(self) -> None:
        if not self.files:
            self.load_files(self.folder)
        with contextlib.closing(PIL.Image.open(self.files[self.index])) as img:
            self.frames = []
            for frame in PIL.ImageSequence.Iterator(img):
                duration = frame.info.get("duration", 100)
                loop = frame.info.get("loop", 0)
                frame = PIL.ImageOps.pad(
                    frame.convert("RGB"),
                    (self.width, self.height),
                    method=PIL.Image.NEAREST,
                    centering=(0.5, 0.5),
                )
                self.frames.append(Frame(frame, duration, loop))

    def play(self) -> bool:
        if not self.frames:
            self.preload()
        for frame in self.frames:
            start = time.monotonic()
            with canvas(self.display) as draw:
                draw.bitmap((0, 0), frame.image, fill="white")
            elapsed = time.monotonic() - start
            if elapsed < 0:
                elapsed = 0
            sleep_time = frame.duration / 1000 - elapsed
            if sleep_time > 0:
                time.sleep(sleep_time)
            if frame.loop == 0:
                continue
            frame.loop -= 1
            if frame.loop == 0:
                return True
        return False

    def run(self) -> None:
        self._is_running = True
        while self._is_running:
            try:
                if not self.play():
                    self.advance()
            except Exception as e:
                logger.exception(e)
                self.stop()

    def stop(self) -> None:
        self._is_running = False

    def advance(self) -> None:
        self.index += 1
        if self.index >= len(self.files):
            self.index = 0
        self.frames = []


