import time
import subprocess
import logging
from gpiozero import InputDevice

def simulate_light():
    """Simulate light level in lux."""
    if 6 <= time.localtime().tm_hour < 18:
        return 600 + 400 * time.time() % 1
    else:
        return 100 + 200 * time.time() % 1

def simulate_temperature():
    """Simulate temperature in °C."""
    return 20 + 10 * time.time() % 1

def simulate_voltage():
    """Simulate voltage in V."""
    if simulate_light() > 300:
        return 11.5 + 1 * time.time() % 1
    else:
        return 10.0 + 1 * time.time() % 1

def simulate_current():
    """Simulate current in A."""
    if simulate_light() > 300:
        return 1.5 + 1 * time.time() % 1
    else:
        return 0.5 + 1 * time.time() % 1

def read_pi_temperature():
    """Read the Raspberry Pi's internal temperature in °C."""
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=1,
        )
        return float(result.stdout.strip().split('=')[1].rstrip("'C"))
    except (subprocess.TimeoutExpired, ValueError, IndexError):
        logging.warning('Failed to read Pi temperature')
        return None

def main():
    """Main program."""
    logging.basicConfig(
        format='%(asctime)s %(levelname)s %(message)s',
        level=logging.DEBUG,
    )
    logging.info('Initializing GPIO17 and GPIO4')
    light = InputDevice(17, pull_up=False)
    temperature = InputDevice(4, pull_up=False)
    try:
        while True:
            light_level = simulate_light()
            temperature_value = simulate_temperature()
            voltage = simulate_voltage()
            current = simulate_current()
            pi_temperature = read_pi_temperature()
            if light_level < 300:
                logging.warning('Possible solar panel performance issues')
            if temperature_value > 35:
                logging.warning('Simulated cooling system activated')
            if pi_temperature is not None and pi_temperature > 75:
                logging.critical('Simulated system shutdown')
                break
            logging.info(
                'Light: %.1f lux, Temperature: %.1f °C, '
                'Voltage: %.1f V, Current: %.1f A, '
                'Pi temperature: %.1f °C' % (
                    light_level,
                    temperature_value,
                    voltage,
                    current,
                    pi_temperature or 'N/A',
                )
            )
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info('Interrupted')
    finally:
        logging.info('Cleaning up')
        light.close()
        temperature.close()

if __name__ == '__main__':
    main()

