            if (status & 0x18) != 0x18:
                self.logger.error("DHT20 status check failed")
                self.bus.close()
                self.bus = None
                return
        except Exception as e:
            self.logger.error(f"DHT20 init failed: {e}")
            self.bus = None
            return
        self.logger.info("DHT20 init successful")

    def __del__(self):
        if self.bus:
            self.bus.close()

    def get_temperature_and_humidity(self):
        self.crc_error_flag = False
        self.temperature = None
        self.humidity = None
        for i in range(5):
            try:
                self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
                status = self.bus_read_byte_data(0x38, 0x71)
                start_time = time.time()
                while (status & 0x80) != 0:
                    if time.time() - start_time > 0.1:
                        self.logger.warning("DHT20 timeout")
                        break
                    status = self.bus.read_byte_data(0x38, 0x71)
                if (status & 0x80) == 0:
                    data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
                    if self.crc8(data[:6]) == data[6]:
                        self.temperature = data[1] * 256 + data[2]
                        self.temperature = self.temperature / 5242.88 - 50
                        self.humidity = data[3] * 256 + data[4]
                        self.humidity = self.humidity / 1048576 * 100
                        return (self.temperature, self.humidity, self.crc_error_flag)
                    else:
                        self.logger.warning("DHT20 CRC error")
                        self.crc_error_flag = True
                time.sleep(2)
            except Exception as e:
                self.logger.error(f"DHT20 get_temperature_and_humidity failed: {e}")
        return (None, None, True)

    def crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc = crc << 1
        return crc

