import smbus2
import time
import signal
import logging
import sys

class DHT20:
    def __init__(self):
        self.bus = None
        self.crc_error = False
        self.temperature = None
        self.humidity = None
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.DEBUG)
        self.logger.addHandler(logging.StreamHandler())
        self.logger.info("Initializing DHT20")
        try:
            self.bus = smbus2.SMBus(1)
            self.bus.write_i2c_block_data(0x38, 0x71, [0x00])
            self.bus.read_i2c_block_data(0x38, 0x71, 1)
        except IOError as e:
            self.logger.error("I/O error: {0}".format(e))
            self.bus = None
        except Exception as e:
            self.logger.error("Unexpected error: {0}".format(e))
            self.bus = None

    def measure(self):
        self.logger.info("Measuring")
        if self.bus is None:
            self.logger.error("I2C bus not initialized")
            return (None, None, True)
        try:
            self.bus.write_i2c_block_data(0x38, 0xAC, [0x00])
            timeout = 0.1
            while timeout > 0:
                time.sleep(0.01)
                timeout -= 0.01
                status = self.bus.read_i2c_block_data(0x38, 0x71, 1)
                if status[0] & 0x80 == 0:
                    break
            if timeout <= 0:
                self.logger.error("Timeout")
                return (None, None, True)
            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            crc = 0xFF
            for i in range(6):
                crc ^= data[i]
                for j in range(8):
                    if crc & 0x80:
                        crc = (crc << 1) ^ 0x31
                    else:
                        crc = crc << 1
            if crc != data[6]:
                self.logger.error("CRC error")
                self.crc_error = True
            else:
                self.crc_error = False
            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]
            self.temperature = float(temperature_raw) / 5242.88 - 50.0
            self.humidity = float(humidity_raw) / 0x100000 * 100.0
            return (self.temperature, self.humidity, self.crc_error)
        except IOError as e:
            self.logger.error("I/O error: {0}".format(e))
            return (None, None, True)
        except Exception as e:
            self.logger.error("Unexpected error: {0}".format(e))
            return (None, None, True)

    def __del__(self):
        self.logger.info("Closing DHT20")
        if self.bus is not None:
            self.bus.close()

def signal_handler(sig, frame):
    print("Exiting")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
