import RPi.GPIO as GPIO
import time
import threading
import sys

class DOG:
    def __init__(self):
        self.data = ""
        self.receive_thread = None
        self.file = None
        self.running = False

    def send(self, data):
        # Send data using DOG.send()
        print("Sending data:", data)

    def receive(self):
        # Receive data using DOG.receive()
        return "Received data"

    def start(self, filename):
        # Start the logging thread
        self.file = open(filename, "w")
        self.running = True
        self.receive_thread = threading.Thread(target=self.receive_loop)
        self.receive_thread.start()

    def stop(self):
        # Stop the server and the receive thread
        self.running = False
        self.receive_thread.join()
        self.file.close()

    def receive_loop(self):
        # Receive data and write to the file
        while self.running:
            data = self.receive()
            self.file.write(data + "\n")
            self.file.flush()
            time.sleep(0.1)

    def help(self, command=None):
        # Display help
        if command is None:
            print("Available commands: start, stop, help, display, send, write, exit")
        else:
            if command == "start":
                print("Usage: start <filename>")
            elif command == "stop":
                print("Usage: stop")
            elif command == "help":
                print("Usage: help [command]")
            elif command == "display":
                print("Usage: display")
            elif command == "send":
                print("Usage: send <data>")
            elif command == "write":
                print("Usage: write <data>")
            elif command == "exit":
                print("Usage: exit")
            else:
                print("Invalid command")

    def display(self):
        # Print the contents of the log file
        if self.file is not None:
            self.file.seek(0)
            print(self.file.read())
        else:
            print("Log file not open")

    def send_data(self, data):
        # Send data using DOG.send()
        self.send(data)

    def write_data(self, data):
        # Write data directly to the log file with a newline character
        if self.file is not None:
            self.file.write(data + "\n")
            self.file.flush()
        else:
            print("Log file not open")

    def exit(self):
        # Stop the server, clean up GPIO, and exit
        self.stop()
        GPIO.cleanup()
        sys.exit(0)

def signal_handler(signal, frame):
    # Handle SIGINT/SIGTERM
    dog.exit()

def main():
    # Initialize GPIO
    GPIO.setmode(GPIO.BCM)

    # Create an instance of DOG
    dog = DOG()

    # Set up signal handler
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Main loop
    while True:
        command = input("> ")
        if command.startswith("start"):
            filename = command.split(" ")[1]
            dog.start(filename)
        elif command == "stop":
            dog.stop()
        elif command.startswith("help"):
            command_parts = command.split(" ")
            if len(command_parts) == 1:
                dog.help()
            else:
                dog.help(command_parts[1])
        elif command == "display":
            dog.display()
        elif command.startswith("send"):
            data = command.split(" ")[1]
            dog.send_data(data)
        elif command.startswith("write"):
            data = command.split(" ")[1]
            dog.write_data(data)
        elif command == "exit":
            dog.exit()
        else:
            print("Invalid command")

if __name__ == "__main__":
    main()

