import pigpio
import threading

class OutputPin:
    def __init__(self, pin, value_list, initial_value):
        self.pin = pin
        self.value_list = value_list
        self.current_value = initial_value
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("pigpio connection failed")
        if self.pin not in self.pi.get_hardware_revision():
            raise ValueError("invalid pin number")
        if self.current_value not in self.value_list:
            raise ValueError("invalid initial value")
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.write(self.pin, self.current_value)

    def shutdown(self):
        self.pi.set_mode(self.pin, pigpio.INPUT)
        self.pi.stop()

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError("invalid value")
        self.pi.write(self.pin, value)
        self.current_value = value

class TriggerPin(OutputPin):
    def __init__(self, pin, pulse_duration, pulse_high):
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.lock = threading.Lock()
        super().__init__(pin, (0, 1), 0)

    def trigger(self):
        with self.lock:
            self.pi.write(self.pin, self.pulse_high)
            self.pi.set_watchdog(self.pin, self.pulse_duration)
            self.pi.write(self.pin, not self.pulse_high)

def main():
    try:
        ExampleOutput = OutputPin(21, (0, 1), 0)
        ExampleTrigger = TriggerPin(20, 100, True)
        ExampleTrigger.trigger()
    except Exception as e:
        print(e)
    finally:
        ExampleOutput.shutdown()
        ExampleTrigger.shutdown()

if __name__ == "__main__":
    main()

