from sys import exit
from time import sleep

class LEDController:
    def __init__(self, pin):
        try:
            self.led = LED(pin)
        except ValueError as e:
            print(f"Error initializing LED: {e}")
            exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            print("Error: durations must be non-negative")
            exit(1)
        self.led.blink(on_duration, off_duration)

def main():
    controller = LEDController(25)
    try:
        while True:
            controller.blink(1.0, 0.5)
    except KeyboardInterrupt:
        controller.off()
        exit(0)

if __name__ == "__main__":
    signal(SIGINT, lambda s, f: exit(0))
    signal(SIGTERM, lambda s, f: exit(0))
    main()
```

