import json
import random

def transcribe(energy):
    if energy % 3 == 0:
        return 'water'
    elif energy % 3 == 1:
        return 'stop'
    else:
        return 'status'

def farm_action(word):
    if word == 'water':
        return 'open_valve'
    elif word == 'stop':
        return 'close_valve'
    else:
        return 'report'

def main():
    actions = []
    try:
        for i in range(6):
            energy = random.randint(0, 9)
            word = transcribe(energy)
            action = farm_action(word)
            print(f'Frame {i}: {word} -> {action}')
            actions.append(action)
    except Exception as e:
        print(f'Error: {e}')
    finally:
        with open('voice_actions.json', 'w') as f:
            json.dump(actions, f)

if __name__ == '__main__':
    main()
