# Register addresses of the MPU-6050 sensor
PWR_MGMT_1 = 0x6B
GYRO_CONFIG = 0x1B
GYRO_XOUT_H = 0x43
GYRO_XOUT_L = 0x44
GYRO_YOUT_H = 0x45
GYRO_YOUT_L = 0x46
GYRO_ZOUT_H = 0x47
GYRO_ZOUT_L = 0x48

# Sensitivity scale factor of the gyroscope
GYRO_SCALE_FACTOR = 131.0

# Calibration offset for the gyroscope
CALIBRATION_OFFSET = 0.0

