    return (x - CALIBRATION_OFFSET[0]) / GYRO_SCALE_FACTOR, (y - CALIBRATION_OFFSET[1]) / GYRO_SCALE_FACTOR, (z - CALIBRATION_OFFSET[2]) / GYRO_SCALE_FACTOR

