def estimate_orientation(x, y, z, dt):
    roll = 0.0
    pitch = 0.0
    yaw = 0.0
    for _ in range(int(1 / dt)):
        roll += x * dt
        pitch += y * dt
        yaw += z * dt
    return roll, pitch, yaw

