import smbus2
import time
import csv
import argparse

# I2C address of the MPU-6050 sensor
MPU6050_ADDR = 0x68

# Register addresses of the MPU-6050 sensor
PWR_MGMT_1 = 0x6B
GYRO_CONFIG = 0x1B
GYRO_XOUT_H = 0x43
GYRO_XOUT_L = 0x44
GYRO_YOUT_H = 0x45
GYRO_YOUT_L = 0x46
GYRO_ZOUT_H = 0x47
GYRO_ZOUT_L = 0x48

# Sensitivity scale factor of the gyroscope
GYRO_SCALE_FACTOR = 131.0

# Calibration offset for the gyroscope
CALIBRATION_OFFSET = 0.0

# Sample rate in Hz
SAMPLE_RATE = 20

# Duration in seconds
DURATION = 60

# I2C bus number
I2C_BUS = 1

# CSV file name
CSV_FILE = "data.csv"

# Function to read a 16-bit signed integer from the MPU-6050 sensor
def read_int16(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return data[0] << 8 | data[1]

# Function to read the raw gyroscope data from the MPU-6050 sensor
def read_gyro_raw(bus, addr):
    x = read_int16(bus, addr, GYRO_XOUT_H)
    y = read_int16(bus, addr, GYRO_YOUT_H)
    z = read_int16(bus, addr, GYRO_ZOUT_H)
    return x, y, z

# Function to calibrate the gyroscope
def calibrate_gyro(bus, addr):
    global CALIBRATION_OFFSET
    x_sum = 0.0
    y_sum = 0.0
    z_sum = 0.0
    for _ in range(100):
        x, y, z = read_gyro_raw(bus, addr)
        x_sum += x
        y_sum += y
        z_sum += z
        time.sleep(0.05)
    CALIBRATION_OFFSET = (x_sum / 100.0, y_sum / 100.0, z_sum / 100.0)

# Function to convert the raw gyroscope data to degrees per second
def convert_to_dps(x, y, z):
    return (x - CALIBRATION_OFFSET[0]) / GYRO_SCALE_FACTOR, (y - CALIBRATION_OFFSET[1]) / GYRO_SCALE_FACTOR, (z - CALIBRATION_OFFSET[2]) / GYRO_SCALE_FACTOR

# Function to estimate the orientation using integration
def estimate_orientation(x, y, z, dt):
    roll = 0.0
    pitch = 0.0
    yaw = 0.0
    for _ in range(int(1 / dt)):
        roll += x * dt
        pitch += y * dt
        yaw += z * dt
    return roll, pitch, yaw

# Function to write the data to a CSV file
def write_to_csv(timestamp, x, y, z, roll, pitch, yaw):
    with open(CSV_FILE, "a", newline="") as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow([timestamp, x, y, z, roll, pitch, yaw])

# Function to handle Ctrl+C
def handle_ctrl_c(signum, frame):
    print("Exiting gracefully...")
    bus.close()
    exit(0)

# Function to handle I2C bus open failure
def handle_i2c_bus_open_failure(error):
    print("Failed to open I2C bus:", error)
    exit(1)

# Function to handle sensor communication failure
def handle_sensor_communication_failure(error):
    print("Failed to communicate with the sensor:", error)
    exit(1)

# Function to handle file write failure
def handle_file_write_failure(error):
    print("Failed to write to the CSV file:", error)
    exit(1)

# Function to handle I2C bus release failure
def handle_i2c_bus_release_failure(error):
    print("Failed to release the I2C bus:", error)
    exit(1)

# Function to handle file release failure
def handle_file_release_failure(error):
    print("Failed to release the CSV file:", error)
    exit(1)

