import board
import busio
import signal
import sys
import time
from PIL import Image
from adafruit_tcs34725 import TCS34725

def get_sensor_color_data():
    try:
        return tcs.color_rgb_bytes
    except OSError:
        print("Error reading sensor color data")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        image = Image.open(image_path)
        image = image.resize((100, 100))
        colors = image.getcolors(10000)
        return max(colors, key=lambda x: x[0])[1]
    except FileNotFoundError:
        print("Image file not found")
        return (0, 0, 0)
    except OSError:
        print("Error reading image file")
        return (0, 0, 0)

def signal_handler(signal, frame):
    print("Cleaning up")
    i2c.deinit()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

i2c = busio.I2C(board.SCL, board.SDA)

try:
    tcs = TCS34725(i2c, integration_time=TCS34725.INTEGRATION_TIME_50MS, gain=TCS34725.GAIN_4X)
except OSError:
    print("Error initializing I2C bus")
    sys.exit(1)

while True:
    sensor_color_data = get_sensor_color_data()
    dominant_image_color = find_dominant_image_color("image.jpg")
    print(f"Sensor color data: {sensor_color_data}")
    print(f"Dominant image color: {dominant_image_color}")
    time.sleep(1)

