import RPi.GPIO as GPIO
import time
import random

# Constants
STEPS_PER_DEGREE = 12
STEPS_PER_ML = 25

# Setup
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)

# Motor 1
GPIO.setup(17, GPIO.OUT)
GPIO.setup(18, GPIO.OUT)
GPIO.setup(27, GPIO.OUT)
GPIO.setup(22, GPIO.OUT)

# Motor 2
GPIO.setup(23, GPIO.OUT)
GPIO.setup(24, GPIO.OUT)
GPIO.setup(25, GPIO.OUT)
GPIO.setup(12, GPIO.OUT)

# Motor 1
def motor1_step(step):
    if step == 0:
        GPIO.output(17, 1)
        GPIO.output(18, 0)
        GPIO.output(27, 0)
        GPIO.output(22, 0)
    elif step == 1:
        GPIO.output(17, 0)
        GPIO.output(18, 1)
        GPIO.output(27, 0)
        GPIO.output(22, 0)
    elif step == 2:
        GPIO.output(17, 0)
        GPIO.output(18, 0)
        GPIO.output(27, 1)
        GPIO.output(22, 0)
    elif step == 3:
        GPIO.output(17, 0)
        GPIO.output(18, 0)
        GPIO.output(27, 0)
        GPIO.output(22, 1)

# Motor 2
def motor2_step(step):
    if step == 0:
        GPIO.output(23, 1)
        GPIO.output(24, 0)
        GPIO.output(25, 0)
        GPIO.output(12, 0)
    elif step == 1:
        GPIO.output(23, 0)
        GPIO.output(24, 1)
        GPIO.output(25, 0)
        GPIO.output(12, 0)
    elif step == 2:
        GPIO.output(23, 0)
        GPIO.output(24, 0)
        GPIO.output(25, 1)
        GPIO.output(12, 0)
    elif step == 3:
        GPIO.output(23, 0)
        GPIO.output(24, 0)
        GPIO.output(25, 0)
        GPIO.output(12, 1)

# Adjust bed
def adjust_bed(motor_number, angle_degrees):
    if motor_number == 1:
        for i in range(STEPS_PER_DEGREE * angle_degrees):
            for step in range(4):
                motor1_step(step)
                time.sleep(0.002)
    elif motor_number == 2:
        for i in range(STEPS_PER_DEGREE * angle_degrees):
            for step in range(4):
                motor2_step(step)
                time.sleep(0.002)
    for i in range(10):
        if motor_number == 1:
            for step in range(4):
                motor1_step(step)
                time.sleep(0.002)
        elif motor_number == 2:
            for step in range(4):
                motor2_step(step)
                time.sleep(0.002)

# Dispense medication
def dispense_medication(motor_number, dose_ml):
    if motor_number == 1:
        for i in range(STEPS_PER_ML * dose_ml):
            for step in range(4):
                motor1_step(step)
                time.sleep(0.002)
    elif motor_number == 2:
        for i in range(STEPS_PER_ML * dose_ml):
            for step in range(4):
                motor2_step(step)
                time.sleep(0.002)
    for i in range(10):
        if motor_number == 1:
            for step in range(4):
                motor1_step(step)
                time.sleep(0.002)
        elif motor_number == 2:
            for step in range(4):
                motor2_step(step)
                time.sleep(0.002)

# Read heart rate
def read_heart_rate():
    return random.randint(60, 100)

# Read SpO2
def read_spo2():
    return random.randint(95, 99)

# Run schedule
def run_schedule(head_angle, foot_angle, dose_A, dose_B, interval_seconds):
    if head_angle < 1 or head_angle > 30:
        print("Invalid head angle")
        return
    if foot_angle < 1 or foot_angle > 30:
        print("Invalid foot angle")
        return
    if dose_A < 1 or dose_A > 10:
        print("Invalid dose A")
        return
    if dose_B < 1 or dose_B > 10:
        print("Invalid dose B")
        return
    if interval_seconds < 60 or interval_seconds > 300:
        print("Invalid interval")
        return
    adjust_bed(1, head_angle)
    adjust_bed(2, foot_angle)
    dispense_medication(1, dose_A)
    dispense_medication(2, dose_B)
    print("Heart rate:", read_heart_rate())
    print("SpO2:", read_spo2())

# Main loop
try:
    while True:
        run_schedule(15, 10, 5, 3, 120)
        time.sleep(120)
except KeyboardInterrupt:
    GPIO.cleanup()

from gpiozero import LED
import time

led = LED(17)
moisture = 60

try:
    while True:
        if moisture <= 0:
            moisture = 60
        moisture -= 3
        if moisture <= 30:
            led.on()
        else:
            led.off()
        print(f"Moisture: {moisture}, LED: {'ON' if led.is_lit else 'OFF'}")
        time.sleep(2)
except KeyboardInterrupt:
    print("Program interrupted by user")
except Exception as e:
    print(f"Error: {e}")
finally:
    led.off()
    print("Program exiting")

