from adafruit_servokit import ServoKit
from time import sleep

BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

METAL = 135
PLASTIC = 180
PAPER = 90

def move_servo(channel, target_angle, step_size=5, delay=0.04):
    if channel < 0 or channel > 15:
        raise ValueError("Invalid channel")
    if target_angle < 0 or target_angle > 180:
        raise ValueError("Invalid angle")
    current_angle = kit.servo[channel].angle
    if current_angle is None:
        raise ValueError("Invalid angle")
    if current_angle == target_angle:
        return
    if current_angle < target_angle:
        step_size = -step_size
    for angle in range(current_angle, target_angle, step_size):
        kit.servo[channel].angle = angle
        sleep(delay)

def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, angle)

def drop(angle):
    move_servo(DROP, angle, step_size=2, delay=0.01)

def pick(angle):
    move_servo(GRAB, angle)

def grab(angle):
    move_servo(GRAB, angle)

def release(angle):
    move_servo(GRAB, angle)

def collect_object_steps(seek_angle):
    seek(seek_angle)
    pick(90)
    drop(160)
    pick(100)
    deseek(seek_angle)

def drop_object_steps(drop_angle):
    drop(drop_angle)
    release(120)
    drop(100)

