#!/usr/bin/env python3

import serial
import time
import datetime
import sys
import os

def main():
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            while True:
                try:
                    payload = ser.readline().decode('ascii', 'replace')
                    if payload:
                        try:
                            co2 = int(payload)
                            print(f'{datetime.datetime.now().isoformat()}: {co2} ppm')
                            with open('co2_readings_log.txt', 'a') as log:
                                log.write(f'{datetime.datetime.now().isoformat()}: {co2} ppm\n')
                        except ValueError:
                            print(f'Invalid payload: {payload}')
                    else:
                        print('No payload')
                except serial.SerialException as e:
                    print(f'Serial error: {e}')
                time.sleep(5)
    except KeyboardInterrupt:
        print('Exiting')
    except Exception as e:
        print(f'Unexpected error: {e}')
        sys.exit(1)

if __name__ == '__main__':
    main()
```

