@dataclasses.dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self):
        self.port = None

    def connect(self):
        try:
            self.port = serial.Serial(
                port='/dev/serial0',
                baudrate=9600,
                timeout=1,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                bytesize=serial.EIGHTBITS,
            )
        except serial.SerialException as e:
            logging.error(f'Failed to open serial port: {e}')
            raise

    def disconnect(self):
        if self.port:
            self.port.close()
            self.port = None

    def read_gps(self):
        while True:
            try:
                line = self.port.readline().decode('ascii')
            except serial.SerialException as e:
                logging.error(f'Serial read failed: {e}')
                continue
            except UnicodeDecodeError as e:
                logging.error(f'Invalid serial data: {e}')
                continue

            if not line:
                logging.warning('Serial read timeout')
                continue

            if not line.startswith('$GPGGA'):
                continue

            fields = line.split(',')
            if len(fields) != 15:
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            if fields[6] == '':
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            try:
                satellite_count = int(fields[7])
            except ValueError as e:
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            try:
                altitude = float(fields[9])
            except ValueError as e:
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            try:
                latitude = float(fields[2])
                latitude_sign = 1 if fields[3] == 'N' else -1
                latitude = latitude_sign * (latitude // 100 + (latitude % 100) / 60)
            except ValueError as e:
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            try:
                longitude = float(fields[4])
                longitude_sign = 1 if fields[5] == 'E' else -1
                longitude = longitude_sign * (longitude // 100 + (longitude % 100) / 60)
            except ValueError as e:
                logging.error(f'Invalid GPGGA sentence: {line}')
                continue

            yield GPS_readings(latitude, longitude, altitude, satellite_count)

def signal_handler(signum, frame):
    logging.info('Received signal, exiting')
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader = GPSReader()
    try:
        reader.connect()
        for reading in reader.read_gps():
            logging.info(f'GPS reading: {reading}')
    except Exception as e:
        logging.error(f'Unhandled exception: {e}')
    finally:
        reader.disconnect()

