import logging
from gpiozero import DigitalInputDevice, DigitalOutputDevice

class SimpleGPIO:
    def __init__(self):
        self.pins = {}

    def set_pin_mode(self, pin, mode, pull_up_down):
        try:
            if mode == 'input':
                self.pins[pin] = DigitalInputDevice(pin, pull_up=pull_up_down == 'up')
            elif mode == 'output':
                self.pins[pin] = DigitalOutputDevice(pin, pull_up=pull_up_down == 'up')
            else:
                return False
            return True
        except ValueError as e:
            logging.error(f'ValueError: {e}')
            return False

    def write_digital(self, pin, value):
        try:
            if pin not in self.pins or not isinstance(self.pins[pin], DigitalOutputDevice):
                return False
            self.pins[pin].value = value
            return True
        except ValueError as e:
            logging.error(f'ValueError: {e}')
            return False

    def read_digital(self, pin):
        try:
            if pin not in self.pins or not isinstance(self.pins[pin], DigitalInputDevice):
                return None
            return self.pins[pin].value
        except ValueError as e:
            logging.error(f'ValueError: {e}')
            return None

if __name__ == '__main__':
