import logging
import smbus2

class SimpleI2C:
    def __init__(self):
        self.connection = None

    def connect(self, bus, address, timeout):
        try:
            self.connection = smbus2.SMBus(bus, timeout=timeout)
            return True
        except smbus2.SMBusException as e:
            logging.error(f'SMBusException: {e}')
            return False

    def read_byte(self, register):
        try:
            if self.connection is None:
                return None
            return self.connection.read_byte_data(register)
        except smbus2.SMBusException as e:
            logging.error(f'SMBusException: {e}')
            return None

    def write_byte(self, register, byte):
        try:
            if self.connection is None:
                return False
            self.connection.write_byte_data(register, byte)
            return True
        except smbus2.SMBusException as e:
            logging.error(f'SMBusException: {e}')
            return False

    def close(self):
        try:
            if self.connection is not None:
                self.connection.close()
